// EXPERIMENT 2 — does a self-description survive a semantic mutation?
//
// Arm A's real question is the smallest credible path from a conventional source
// file to a TRUTHFUL, self-describing file. This probe attacks that directly.
//
// Method: take the pinned fixture, mutate `add` from addition to multiplication
// WITHOUT changing any type signature, then re-derive the description through two
// independent channels and ask which one notices:
//
//   CHANNEL T (type-derived):  facts a compiler can establish. Types, arity,
//                              exports. Regenerated by the TS typeChecker.
//   CHANNEL O (observed):      facts witnessed by actually executing probes.
//
// Falsifiable prediction: if a self-description is built only from Channel T, it
// will be BYTE-IDENTICAL before and after the mutation, and therefore a reader
// relying on it is actively misled while every type still checks out.
//
// Evidence class: TESTED (both channels executed against real artifacts).
// Usage: node exp2-mutation.mjs
import {execFileSync} from 'node:child_process';
import {readFileSync, writeFileSync, mkdtempSync, readdirSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';

const require = createRequire(import.meta.url);
const TS_PKG = 'C:/Users/VIVIM.inc/AppData/Local/npm-cache/_npx/da912b5ea09ad757/node_modules/typescript';
const TSC = `${TS_PKG}/lib/tsc.js`;
const tsc = (...args) => execFileSync(process.execPath, [TSC, ...args], {encoding: 'utf8'});

const ORIGINAL = readFileSync('baseline.ts', 'utf8');
const MUTATED = ORIGINAL.replace('return a + b;', 'return a * b;');
if (MUTATED === ORIGINAL) throw new Error('mutation did not apply — refusing to report a no-op as a result');

function compileAndRun(source, tag) {
  const dir = mkdtempSync(join(tmpdir(), `runa-e2-${tag}-`));
  const p = join(dir, 'm.ts');
  writeFileSync(p, source);
  tsc(p, '--outDir', dir, '--module', 'commonjs', '--target', 'es2020', '--strict');
  const mod = require(join(dir, 'm.js'));
  // Execute observable behavior: this is the ONLY channel that can witness a
  // body-only mutation, because the mutation leaves every type untouched.
  const out = [];
  for (let i = 0; i < 5; i++) out.push(mod.add(i, 10));
  return {add: mod.add, addSeries: out, dir};
}

// ---- CHANNEL T: the type-derived description ------------------------------
function typeDescription(source, tag) {
  const dir = mkdtempSync(join(tmpdir(), `runa-e2t-${tag}-`));
  const p = join(dir, 'm.ts');
  writeFileSync(p, source);
  const out = execFileSync(process.execPath, [TSC, p, '--outDir', dir, '--declaration', '--emitDeclarationOnly', '--module', 'commonjs', '--target', 'es2020', '--strict'], {encoding: 'utf8', stdio: 'pipe'});
  const dts = readFileSync(join(dir, 'm.d.ts'), 'utf8').replace(/\r\n/g, '\n').trim();
  return {declaration: dts, diagnostics: (out || '').trim()};
}

const before = compileAndRun(ORIGINAL, 'before');
const after = compileAndRun(MUTATED, 'after');

const tBefore = typeDescription(ORIGINAL, 'before');
const tAfter = typeDescription(MUTATED, 'after');

const observedBefore = JSON.stringify(before.addSeries);
const observedAfter = JSON.stringify(after.addSeries);
const typeIdentical = tBefore.declaration === tAfter.declaration;

// Both versions still typecheck cleanly -- the mutation is invisible to the compiler.
let bothTypecheck = true;
try {
  typeDescription(ORIGINAL, 'check1');
  typeDescription(MUTATED, 'check2');
} catch { bothTypecheck = false; }

console.log(JSON.stringify({
  experiment: 'EXP2 — does a self-description survive a body-only semantic mutation?',
  evidenceClass: 'TESTED',
  mutation: 'return a + b;  ->  return a * b;',
  mutationChangesAnyTypeSignature: false,
  bothVersionsTypecheckUnderStrict: bothTypecheck,
  channelT_typeDerived: {
    before: tBefore.declaration,
    after: tAfter.declaration,
    identical: typeIdentical,
    verdict: typeIdentical
      ? 'UNDETECTED — every type-derived description is byte-identical after the mutation'
      : 'detected',
  },
  channelO_observed: {
    before: before.addSeries,
    after: after.addSeries,
    identical: observedBefore === observedAfter,
    verdict: observedBefore === observedAfter ? 'UNDETECTED' : 'DETECTED — witnessed divergence',
  },
  sourceSha256: {
    original: createHash('sha256').update(ORIGINAL).digest('hex'),
    mutated: createHash('sha256').update(MUTATED).digest('hex'),
  },
}, null, 2));
